-- chair-step: inverse of read_lane_v2_b3_30_workbench_google_document — un-enrolls workbench.google_document from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'google_document' and is_active);
select iam.apply_rls('workbench', 'google_document', (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'google_document' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workbench' and table_name = 'google_document' and is_active));
